// Kontrollerar F59 Marknadssida: sidan finns, inget skript, exakt tre länkar i rätt ordning, länkarna leder till filer,
// ingen spårning (inga parametrar, utm, bilder eller formulär), inga .html-länkar, AI-märkning, integritetsraden,
// ingen länk från startsidan och – om sidkartan finns på main – en rad i sidkartan.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const path = require('path');

const pub = 'public';
const fil = path.join(pub, 'marknad.html');
const finns = fs.existsSync(fil);
const html = finns ? fs.readFileSync(fil, 'utf8') : '';
const utanKommentarer = html.replace(/<!--[\s\S]*?-->/g, '');
const hrefs = [...utanKommentarer.matchAll(/href="([^"]*)"/g)].map((m) => m[1]);
const srcs = [...utanKommentarer.matchAll(/src="([^"]*)"/g)].map((m) => m[1]);
const fattas = [];

// 1. Sidan finns.
const sidanFinns = finns &&
  /<html lang="sv">/.test(html) &&
  /<meta charset="utf-8">/i.test(html) &&
  /<h1>Välkommen från adventsmarknaden<\/h1>/.test(html) &&
  hrefs.includes('#innehall') &&
  /<meta name="robots" content="noindex">/.test(html);

// 2. Inget skript och inga absoluta adresser.
const ingetSkript = finns && !/<script/i.test(html) && !/(src|href)="https?:\/\//i.test(html);

// 3. Exakt tre länkar i ul.marknad, i rätt ordning.
const lista = (utanKommentarer.match(/<ul class="marknad">([\s\S]*?)<\/ul>/) || [, ''])[1];
const listLankar = [...lista.matchAll(/href="([^"]*)"/g)].map((m) => m[1]);
const treLankar = JSON.stringify(listLankar) === JSON.stringify(['/', '/vreta-sound-system', '/sa-marker-vi-ai']);
if (!treLankar) fattas.push('listan har ' + JSON.stringify(listLankar));

// 4. Varje intern länk utan # motsvarar en fil.
const interna = hrefs.filter((h) => h.startsWith('/') && !h.includes('#'));
function harFil(h) {
  if (h === '/') return fs.existsSync(path.join(pub, 'index.html'));
  const v = h.replace(/^\//, '').replace(/\/$/, '');
  return fs.existsSync(path.join(pub, v + '.html')) || fs.existsSync(path.join(pub, v, 'index.html'));
}
for (const h of interna) if (!harFil(h)) fattas.push('länken leder inte till en fil: ' + h);
const lankarnaFinns = finns && interna.length > 0 && interna.every(harFil);

// 5. Ingen spårning.
const ingenSparning = finns &&
  ![...hrefs, ...srcs].some((u) => u.includes('?') || /utm_|utm\.js/.test(u)) &&
  !/<img/i.test(html) && !/<form/i.test(html);

// 6. Inga .html-länkar.
const ingaHtmlLankar = finns && !hrefs.some((h) => /\.html(#|$)/.test(h));

// 7. AI-märkning.
const aiMarkt = html.includes('AI-skapat') && html.includes('AI-skapade roller') && html.includes('Generated by AI, Directed by MS');

// 8. Integritetsraden.
const integritetsrad = html.includes('<h2>Vi vet inte vem du är</h2>') && html.includes('Sidan sparar inga kakor');

// 9. Ingen länk från startsidan.
const index = fs.readFileSync(path.join(pub, 'index.html'), 'utf8');
const intePaStartsidan = !index.includes('href="/marknad"');

// 10. Sidkartan, om den finns.
const kartfil = path.join(pub, 'sidkarta.html');
const kartaFinns = fs.existsSync(kartfil);
const sidkartanOmDenFinns = kartaFinns ? fs.readFileSync(kartfil, 'utf8').includes('href="/marknad"') : true;

const krav = { sidanFinns, ingetSkript, treLankar, lankarnaFinns, ingenSparning, ingaHtmlLankar, aiMarkt, integritetsrad, intePaStartsidan, sidkartanOmDenFinns };
const ok = Object.values(krav).every(Boolean);
const ut = { ...krav, ok };
if (!kartaFinns) ut.sidkarta = 'saknas på main, raden läggs av den PR som slås ihop sist';
if (!ok && fattas.length) console.error(fattas.join('\n'));
console.log(JSON.stringify(ut));
process.exit(ok ? 0 : 1);
